const tabId = 248688717;
const res = await browserjs(tabId, () => {
  const h2s = Array.from(document.querySelectorAll('h2'));
  const trendingH2 = h2s.find(h => h.textContent.includes('Trending events near Boston'));
  if (!trendingH2) return "Not found";

  // traverse up to find the section containing trending events
  let cur = trendingH2;
  while (cur && cur.querySelectorAll('a').length < 5) {
    cur = cur.parentElement;
  }

  const cards = Array.from(cur.querySelectorAll('a')).map(a => {
    return {
      href: a.href,
      text: a.closest('div[class*="Card"], li, div[class*="bway-"]')?.textContent?.trim().replace(/\s+/g, ' ')
    };
  });

  const buttons = Array.from(cur.querySelectorAll('button')).map(b => ({
    ariaLabel: b.getAttribute('aria-label'),
    text: b.textContent.trim(),
    outer: b.outerHTML.slice(0, 150)
  }));

  return {
    curTag: cur?.tagName,
    cardsCount: cards.length,
    cards: cards.filter(c => c.text && c.text.length > 10),
    buttons
  };
});
console.log(JSON.stringify(res, null, 2));

