const tabId = 248688717;
const res = await browserjs(tabId, async () => {
  // Let's fetch all sports events in Boston from getExploreEvents across pages (page=0, 1, 2, ...)
  const allEvents = [];
  let page = 0;
  while (page < 10) {
    const url = `https://www.stubhub.com/explore?method=getExploreEvents&lat=NDIuMzU1NTA3Ng%3D%3D&lon=LTcxLjA1NjUzNjQ%3D&tlcId=2&page=${page}`;
    const resp = await fetch(url);
    const json = await resp.json();
    if (!json.events || json.events.length === 0) break;
    allEvents.push(...json.events);
    if (json.remaining === 0) break;
    page++;
  }
  return {
    totalFetched: allEvents.length,
    events: allEvents.map(e => ({
      id: e.eventId,
      name: e.name,
      date: `${e.dayOfWeek}, ${e.formattedDateWithoutYear} - ${e.formattedTime}`,
      venue: e.venueName,
      location: e.formattedVenueLocation,
      catId: e.categoryId,
      url: e.url
    }))
  };
