    const url = `https://www.stubhub.com/explore?method=getExploreEvents&lat=NDIuMzU1NTA3Ng%3D%3D&lon=LTcxLjA1NjUzNjQ%3D&page=${page}`;
    const resp = await fetch(url);
    const json = await resp.json();
    if (!json.events || json.events.length === 0) break;
    allEvents.push(...json.events);
    if (json.remaining === 0) break;
    page++;
  }

  // Find all events at TD Garden or with Bruins or NHL
  const tdGardenEvents = allEvents.filter(e => 
    e.venueName?.toLowerCase().includes('garden') ||
